    story: "苏轼在杭州做通判的几年里，公务之余常到西湖上饮酒。熙宁六年前后的一天，他跟朋友泛舟湖上，开头阳光好，水面闪着光；过了一会儿天色转暗，下起雨来，山色一片空蒙。同席的人说扫兴，他却觉得晴有晴的好，雨有雨的奇。他把西湖比作西施，说淡妆浓抹都合适。这个比喻后来流传太广，西湖从此又多了西子湖这个称呼。他在杭州还修过堤、疏过湖，那几年是他自己过得比较舒展的时候。",
