    story: "熙宁五年六月二十七日，苏轼在西湖边的望湖楼上饮酒。那天他喝得有些醉，天色忽然变了：黑云像泼翻的墨，还没遮住山，白亮的雨点就跳进船里来。楼上的人忙着躲，他却看得起劲。忽然一阵卷地风把云雨都吹散了，再往楼下看，水面平静得像天空一样。他把这短短一场骤雨分四句记下来，都是眼里看到的实景。这组诗一共五首，这是第一首，也是传诵最广的一首。",
