      "星河鹭起，",
      "画图难足。",
      "念往昔，",
      "繁华竞逐，",
      "叹门外楼头，",
      "悲恨相续。",
      "千古凭高对此，",
      "谩嗟荣辱。",
      "六朝旧事随流水，",
      "但寒烟衰草凝绿。",
