    tr: "登高远眺，正值故都金陵的晚秋，天气开始变得萧瑟清肃。千里长江澄澈如一匹白练，青翠的山峰攒聚如簇。归来的帆船、离去的船桨都沐浴在夕阳之中，西风从背后吹来，酒旗斜斜地高高挑起。彩绘的游船仿佛浮在淡淡的云中，白鹭从星光下的沙洲飞起，这般美景，再妙的画图也难以描画。追想往昔，六朝君主争相竞逐繁华，可叹那朱门之外、楼头之上，亡国的悲恨接踵相继。千古以来多少人在此登高凭吊，空自叹息荣辱兴衰。六朝旧事都已随着流水远去，只剩寒烟笼罩的衰草，在暮色中凝成一派暗绿。直到今天，那些歌女们还时不时地唱起那首亡国的《后庭花》。",
    notes: [
      ["练", "白色的丝绢。"],
      ["簇", "聚集成堆。"],
      ["门外楼头", "指隋军已兵临建康城下，陈后主还在结绮阁上寻欢作乐。"],
      ["后庭遗曲", "陈后主《玉树后庭花》，被视为亡国之音。"],
    ],
    appr: "金陵怀古词的压卷之作，气象雄浑，据传令同时三十余首同调之作黯然失色。",
    story: "王安石主持变法多年，两次拜相又两次罢相，最后退到江宁居住。晚年他登高远望，眼前正是金陵的晚秋：长江清澈得像一条白练，青翠的山峰簇拥在一起，夕阳里归船来往，酒旗斜斜挑着。风景仍在，六朝却一个接一个亡了。他想起那些旧事，写下门外楼头的悲恨、六朝旧事随流水，最后落到至今商女还唱着后庭遗曲。这首词在当时就被推为金陵怀古第一，据说同时用这个调子写怀古的有三十多家，只有他这首留了下来。",
