    tr: "秋后的蝉鸣凄凉急切，面对着长亭，天色已晚，一阵骤雨刚刚停歇。在京城门外设帐饯别，心中全无饮酒的兴致，正在依依不舍之时，船家已催促着要出发了。握着手，泪眼相看，竟然哽咽得说不出一句话来。想到这一去千里迢迢，烟波浩渺，暮霭沉沉，南方的天空无比辽阔。多情的人自古以来最怕离别，更何况又是在这冷落的深秋时节！今夜酒醒之后，我会到了哪里？怕只是杨柳岸边，吹着晨风，面对一弯残月吧。这一去不知要多少年，想来那些良辰美景，都成了虚设。即便心中有千种柔情蜜意，又去跟谁诉说呢？",
