    appr: "婉约词的离别绝唱，「杨柳岸晓风残月」成为后世最著名的词中画面之一。",
    story: "柳永在汴京待得不算顺，仕途没有着落，决定南下。临走那天，城外的长亭边摆下送别的酒。寒蝉叫得急，一场骤雨刚停，天已经晚了。船家催着开船，他和送行的人握着手，眼泪对着眼泪，一句话都说不出来。船一开，千里烟波，暮色沉沉，南方的天那么阔。他想到今夜酒醒时，人大概正泊在杨柳岸边，只有晓风和一弯残月。这一走经年，再好的景致也没人一起看了。",
