    appr: "「载不动许多愁」把抽象的愁绪化为有重量的事物，化用前人而又出蓝。",
    story: "绍兴五年前后，金兵南下，李清照一路避难到金华。风停了，落花碾进泥里，还留着一点香。天晚了，她连头也懒得梳。身边的东西还在，人却全变了，话没出口眼泪先下来。有人告诉她双溪的春色还不错，她也动了去划船的念头，可随即又想：双溪那种小船，怎么载得动她心里这么多愁。写这首词之前不久，她刚登过金华的八咏楼。",
