    tr: "千古江山依旧，却再也无处寻觅孙权那样的英雄。当年的歌舞楼台、风流事迹，都被历史的风雨吹打净尽了。斜阳映照着荒草老树，在那普通的街巷里，人们说刘裕曾经住在这里。想当年，他金戈铁马，北伐中原，气势如虎，气吞万里。可惜宋文帝元嘉年间草草出兵，本想封狼居胥，结果只落得仓皇北顾。我南归至今已经四十三年，向北眺望，还记得当年扬州一带的连天烽火。怎么忍心回首呢？如今在异族皇帝的祠堂之下，只余下一片神鸦啄食、社鼓咚咚的升平景象。还有谁会来问我：廉颇老了，饭量还好吗？",
