    appr: "用典极多而章法严谨，怀古、议政与自伤融为一炉，是辛词的压卷之作。",
    story: "辛弃疾晚年被起用，到镇江做知府。这时朝中主政的韩侂胄张罗着北伐，辛弃疾却看出准备不足，心里着急。他登上北固亭，望着长江。三国时孙权在这里站住脚跟，南朝刘裕也在这里起家，那些人物如今都找不到了。他又想起元嘉年间那次草率出兵，落得仓皇北顾，正像眼前要做的事。四十三年过去，扬州路上的烽火他还记得。末尾他问：廉颇老了，还能不能吃饭？这话是替自己问的，也是替国家问的。",
