    story: "乾道三年，陆游被罢官，回到山阴镜湖边的三山老家。他从前在朝中主张抗金，得罪了人，如今只能闲住。心里不痛快的时候，他就到附近的山村走一走。村里人拿出腊月里酿的浑酒招待他，丰年里鸡猪肉也备得足。山路一程接一程，水一道又一道，他以为前面没路了，转过弯却看见柳树浓密、花开明亮，又是一个村子。那边箫鼓声起来了，春社快到了，村里人的衣冠还留着古时的朴素。他跟村里人说，以后有月亮的晚上，他要拄着拐杖随时来敲门。",
