    story: "淳熙十三年，陆游奉诏到临安等候任命，住在西湖边的客舍里。他等了不少日子，心里并不痛快。这些年官场的滋味他尝够了，薄得像一层纱，可他还是骑着马来到京城。夜里下了一夜春雨，第二天清早，深巷里就有人在叫卖杏花。白天没别的事，他铺开短纸斜斜地写草书，在晴窗前煮水分茶。他想着，清明还赶得上回家，身上这件素衣，也不必为京城的尘土叹气。",
