    tr: "扬州是淮南东路的名都，竹西亭是览胜的佳处，我解开马鞍，在这段旅程的起点稍作停留。走过当年春风十里的繁华长街，如今满眼都是野生的荠麦青青。自从金兵南下窥伺长江之后，留下的只有废弃的城池和高大的古树，它们至今还在厌恶提起战争。黄昏渐渐降临，凄清的画角声吹送着寒意，回荡在这一座空城之中。风流俊赏的杜牧，若算到今天重新来到这里，也一定要大吃一惊。纵然他有写「豆蔻」的好文笔、做「青楼梦」的妙才，面对这般残破，也难以写出深情了。二十四桥还在，桥下的波心荡漾，一轮冷月默默无声。可怜桥边那些红色的芍药，年年开放，可知道是为谁而生的吗？",
