    story: "姜夔一生没做官，靠朋友接济，四处来往。淳熙三年的冬至，他路过扬州。那夜雪刚停，放眼望去全是野生的荠菜和麦子。进了城，四边冷清，只有一湾寒水发着碧色，天色慢慢暗下来，军营里吹起号角，声音凄凉。他想起杜牧写过的春风十里和二十四桥。可金兵南下打过来以后，这里只剩废池和枯树，人们连说起打仗都厌了。他心里难受，就自己谱了一支曲子，把这层感慨写进去。一位前辈读了，说里面有《诗经·黍离》那样的故国之悲。",
