    story: "蒋捷是宜兴人，宋末考中进士没几年，宋朝就亡了。他不肯出来做元朝的官，四处漂泊，靠教书和写字过日子，人们叫他“竹山先生”。他用听雨做线索，把一生分成几段。年轻时在歌楼听雨，红烛照着罗帐，什么也不愁。壮年听雨在客船上，江面宽，云很低，一只失群的大雁在西风里叫。如今老了，住在僧人的屋檐下，两鬓斑白。他不再分辨悲欢，就让阶前的水一滴一滴落到天亮。这大概是晚年写的，具体在哪一年，已经说不清了。",
