    tr: "从梦中醒来，楼台的门窗已经紧紧锁上；酒醒之后，只见帘幕低低垂着。去年春天的离愁别恨，如今又在同一时节涌上心头。落花纷飞之中，我一个人孤零零地站着，蒙蒙细雨里，燕子却成双成对地飞。还记得初次见到小蘋的时候，她穿着心字形花纹的双层罗衣，在琵琶的弦上诉说心中的相思。当年的明月如今仍在天上，它曾经照着她，像一朵彩云一样翩然归去。",
    notes: [
      ["小蘋", "歌女的名字。"],
      ["心字罗衣", "用心字形图案装饰的罗衣。"],
      ["彩云", "比喻小蘋美丽的身影。"],
    ],
    appr: "「落花人独立，微雨燕双飞」袭用五代翁宏成句而意境全出，是词中名句。",
    story: "晏几道是宰相晏殊的儿子。他生在富贵人家，从小不愁吃穿，可父亲去世以后，家道中落。他自己做官不顺，性子又傲，不肯求人，日子越过越窘。他常想起从前的日子，尤其是几位相识的歌女，其中有一个叫小蘋。他写自己从梦里醒来，楼台锁着，帘幕垂着，去年的那点惆怅又回来了。他记得第一次见小蘋，她穿着绣有双重“心”字的罗衣，弹着琵琶说相思。他也记得那晚的月亮，照着她回去。如今月亮还在，人却早不知去了哪里。",
