    story: "苏轼从杭州调到密州做知州。密州比杭州穷，日子清苦，可他在这里写出了不少气派大的作品。熙宁八年冬天，他带人出城到常山去打猎。左手牵着黄狗，右臂架着苍鹰，随从戴着锦帽，穿着貂裘，上千骑人马卷过平冈。满城的人都出来看太守。他喝着酒，胆子也壮了，说自己虽然两鬓有点白，又有什么关系。他想起汉朝的冯唐，希望朝廷也能派人来重用自己。最后他说，要把弓拉得像满月，朝西北射向天狼星。这首词写完，他自己也很得意。",
