    story: "朱寿昌在鄂州做太守，和苏轼隔着长江往来。苏轼在黄州时，写了这首词寄给他。词从江汉的水写起，水从西边流来，到黄鹤楼下变成深碧的颜色，好像还带着岷山峨眉的云浪和锦江的春色。苏轼说，你是留下好名声的太守，我是个在剑外想回家的旅人。面对这样的风物，他心里有话要说。他不想读《江表传》，一读就想起祢衡，那位狂士死在黄祖手里，只剩鹦鹉洲上一片芦苇。最后他劝朱寿昌多写诗，学李白，接上崔颢题黄鹤楼的那段诗名。",
