    tr: "落日中卷起绣帘，亭下江水与天空连成一片。我知道你为我新建了这座亭子，窗上的青红漆色还湿着。我常常想起在平山堂上，斜倚着枕头看江南烟雨，一只孤鸿远远地没入天际。我认得出醉翁欧阳修的那句话：山色在有无之中。一千顷水面，都像镜子般明净，倒映着碧绿的山峰。忽然浪涛涌起，掀动着一叶小舟上的白发老翁。可笑那兰台公子宋玉，不懂庄子所说的天籁，偏要说风有雌雄之分。只要胸中有一点浩然之气，就能享受这千里快哉之风。",
