    story: "张怀民字偓佺，也贬在黄州，和苏轼住得不远。他在江边盖了一座亭子，苏轼给它取名“快哉亭”。元丰六年，苏轼为这座亭子写了这首词。卷起绣帘，亭下的水和天连成一片。他说，知道你是为我新盖的，窗户上的青红漆还没干。他看着江面，想起从前在平山堂上，靠着枕头看江南烟雨，孤鸿杳杳飞远。江面一千顷，静得像镜子，倒映着青山。忽然风浪起来，一个白头老翁驾着一叶小舟在浪里翻。他说只要心里有浩然之气，千里之外都是快哉风。",
