    tr: "明月洁白如霜，好风清凉如水，清幽的景致无边无际。弯曲的港湾里有鱼跃出，圆圆的荷叶上泻下露珠，这一切都寂寞无人看见。三更鼓声响过，一片落叶铿然坠地，把我的好梦惊醒。夜色茫茫，再去追寻已无处可寻，醒来后把小园走了个遍。我这个天涯倦客，望着山中归乡的路，望断了故园的心思与眼目。燕子楼已空，佳人如今何在？只白白锁着楼中的燕子。古今都像一场梦，何曾有人真正梦醒，只有旧日的欢与新来的怨。将来若有人面对黄楼的夜景，也会为我长声叹息。",
