    tr: "花儿谢了，残红褪去，枝头结出小小的青杏。燕子飞来的时节，碧绿的水流绕着人家。枝上的柳絮被风吹得越来越少，可天涯之大，哪里没有芳草呢。墙里是秋千架，墙外是行人道。墙外的行人，听见墙里佳人荡秋千的笑声。笑声渐渐听不见了，四周渐渐静下来，多情的人反被无情的人惹得烦恼。",
