    story: "这首词没有留下确切的写作年份，明清人大多认为作于苏轼被贬惠州的时候。词里写的是暮春：花落了，残红褪去，枝头结了小小的青杏；燕子飞过，绿水绕着人家。柳絮越吹越少，可天涯哪里没有芳草。墙里有人荡秋千，墙外是行路的人，笑声渐渐听不见了，行人空自烦恼。据说朝云唱到天涯何处无芳草两句就唱不下去，说这让她伤心。",
