    story: "元符二年立春，苏轼在儋耳。那时他被贬到海南已经几年，这里在当时是极远的荒僻之地。立春有鞭打春牛的习俗，人们拿着春杖，插着春幡春胜。他写海上吹来的春风没有边，求春风把桃花染得像肉色一样红，一阵风又把他从酒里吹醒。末了他说，这里不像天边，杨花卷起来倒像雪花。他在儋州住茅屋，缺衣少食，却在这里教书，把中原的学问带到了岛上。",
