    story: "绍圣四年，秦观一贬再贬，到了郴州。他住在旅舍里，春寒未尽，独自关着门。雾把楼台遮住了，月色迷蒙，连渡口都看不清，想找的桃花源更无处可寻。郴江本来绕着郴山流，他却问，它到底为谁流到潇湘去。他收到远方朋友寄来的信和梅花，愁恨一层层堆起来，数不清。苏轼极喜欢最后两句，把它写在扇子上。秦观没能回到北方，几年后死在北归的路上。",
