    story: "绍熙二年冬天，姜夔冒着雪到苏州石湖，拜访范成大。范成大做过大官，也是诗人，两人相处了一个多月。范成大拿出纸来向他索句，还要他作新曲子。姜夔就写了《暗香》《疏影》两首咏梅的词。范成大反复玩赏，让家里的歌女练习演唱，音调和谐婉转，于是给这两首曲子起了名字。词里写旧时的月色照着自己梅边吹笛，又写西湖千树梅花压在寒碧的水上。后来他离开石湖，这两首词就传开了。",
