    tr: "整日看山也不觉得厌倦，买了山就想在这山间养老。山上的花落尽了山却依然长在，山水空自流淌，山自自在清闲。",
    notes: [
      ["买山", "买下山林隐居，用支遁买山典故。"],
      ["自闲", "自在安闲。"],
    ],
    appr: "四句八个「山」字回环往复，读出不厌不争的人生态度，是宋诗里少见的民歌式咏叹。",
    story: "王安石晚年住在江宁钟山。他在山里盖了房子，出门常骑一头驴，遇到人就聊天，不讲究身份。这首《游钟山》里说，他整天看山也看不厌，买下这片山，就是要在这里养老。山花开了又落，山一直在；山水白白流走，山自己闲。四句里句句都有山字，一共八个，像是他晚年心境的写照。他在钟山住了大约十年，一直住到去世。",
