    story: "南宋亡后，刘辰翁回到庐陵须溪老家，不再做官。上元夜里，他看见街上的马队蒙着毡子，是元人的铁骑；笛子吹的是别处的腔调，戏鼓也敲得热闹，可听在他耳里都不是从前那种歌声。他一个人对着青灯坐着，想的是旧日京城的高台明月，是如今山中一年年过去的岁月，还有海上那点还没有熄灭的消息。热闹是别人的，他只能在心里守着那个已经不在了的朝廷。",
