    story: "周邦彦在溧水做知县时，县里有无想山。江南的夏天又闷又湿，地低，山离得近，屋里衣服都返潮，要烧炉子去湿气。他忙完公事，站在小桥上听流水，看树荫落在院子里，觉得这一带安静得连乌鸦和老鹰都自在。可他心里清楚，自己是客。年年像燕子一样飞来，落在别人家的房梁上，什么时候是个头呢。所以他不爱听席上那些急管繁弦，只想先铺好席子和枕头，醉了就睡。",
