    lines: ["秋到边城角声哀，", "烽火照高台。", "悲歌击筑，", "凭高酹酒，", "此兴悠哉。", "多情谁似南山月，", "特地暮云开。", "灞桥烟柳，", "曲江池馆，", "应待人来。"],
    tr: "秋风吹到边城，号角声凄凉，烽火映照着高台。我像高渐离那样击筑悲歌，登高洒酒祭奠，这份豪兴何等悠长。多情有谁比得上终南山的明月，特意为我拨开傍晚的云层。想来灞桥的如烟柳色、曲江的池馆楼台，都在等着我回去吧。",
