    tr: "满怀余恨的宫中怨魂，年年栖在翠绿的庭树间。它忽而呜咽于凉枝，忽而移向暗叶，重新把离愁深深倾诉。西窗外一阵雨过，只听得如玉佩在空中流转，如筝柱被轻轻拨动。镜已昏暗，妆已残损，它还在为谁保持这般娇美的鬓影？铜人泪如铅水，可叹承露盘被携往远方，再难贮盛零露。病弱的翅翼惊觉秋意，枯槁的身形阅尽世事，还能消受几度斜阳。余音更加凄苦，偏偏独自抱着清高，转眼成了凄楚。空自怀想和暖的南风，与那千万缕柳丝。",
