    story: "宋朝亡了以后，王沂孙和周密、张炎几个人结了个词社，写咏物的词，写得很隐。会稽的宋六陵被人盗掘，尸骨散在草里，这事不能明说，他就借一只蝉来说。蝉是齐女的魂变的，年年抱着庭中的树，凉枝上呜咽一声，又移到暗叶里去，把离愁一遍遍诉说。他说到铜仙承露盘被搬走，铅泪像水一样洗。蝉的翅膀病了，形体枯了，还不知能经几度斜阳。最后他问，为什么独自抱着清高，反倒落得这样凄楚。",
