    story: "宋亡以后，蒋捷四处流寓，到了吴江一带。他坐船走松陵那边的水路，经过秋娘渡和泰娘桥。春愁一片，得拿酒来浇。江上船摇着，岸边楼上的酒帘招着。风飘飘，雨萧萧，他一身客袍，想的是什么时候能回家洗干净。词里提到银字笙、心字香，那都是家里才有的事物。他把流光写得很轻：红了樱桃，绿了芭蕉，一年就这么过去了。他不肯在元朝做官，晚年住在竹山，过得清贫。这一路的雨，他都记在了词里。",
