    story: "庆历六年，欧阳修被贬到滁州做知州。他在城西丰山下修了一座亭子，取名丰乐，意思是收成好、百姓乐。他常带人去那里喝酒，也常常一个人去。这一首写的是暮春。夕阳斜了，红树青山，长长的郊野上草色绿得望不到边。他心里清楚春天快过完了，可游人不理会这些，还是来来去去，在亭前踩着落花走。被贬的人本该愁，他却写出了这样一段快活。他在滁州还写了醉翁亭记，两处地方离得不远。",
