    story: "曾巩是建昌军南丰人，这片地方他从小长到大。春天来了，柳条还没转成嫩黄，就仗着东风狂起来，乱糟糟地摆。他看不惯这种样子。柳絮飞起来，能把太阳和月亮都遮住，它却不知道天上还有清霜。这话说的不只是柳。他在朝中见过不少这样的人，得势的时候气焰很高，栽下来的时候没人接。他把这层意思藏在咏柳里，写得像在说树，读起来是在说人。这首诗后来常被人拿来教孩子认人。",
