    story: "曾巩中年在外做官，路过润州，上了北固山的甘露寺，登多景楼。他想把这满眼的好景都收进楼里，靠着栏杆转一圈，四面都通。云乱水光，浮着紫翠；天含着山气，映成青红。一川的钟声梵唱，是淮南的月色；万里的帆樯，是海外的风。他看得入神，回头想想自己，衣服上还带着一路的尘土，年华也渐渐老了。他只能把眼睛和心，交给天边飞得远远的鸿雁。几十年宦游，他很少有这样站在高处的时刻。",
